  "Reviews": "Review",
  "confidence {n}/5": "confidence {n}/5",
  "Rebuttal — due this month": "Rebuttal — 本月截止",
  "If the month ends without a response, the decision uses the reviews as they are.": "如果这个月结束前没有回应，结果就按现有的 review 判定。",
  "We regret to inform you.": "我们遗憾地通知你。",
  "The paper did not get in. The project still exists. Its history stays with it, like a limp.": "论文没中。项目还在。它的历史会一直跟着它，像一条瘸腿。",
  "Revise the evidence": "修订证据",
  "Reframe the story": "重讲故事",
