  "submitted": "投稿",
  "phase-one screening": "一轮筛选",
  "reviews": "review",
  "decision": "结果",
  "conference": "会议",
  "Meanwhile: a side project, coursework, or sleep. Two of these are recommended.": "在此期间：做个副项目、上课，或者睡觉。推荐其中两项。",
  "Approved by your advisor. Pick a venue that is open this month, or set a target and wait for its deadline.": "导师已通过。选一个本月开放的投稿场所，或者先设定目标，等它的 deadline。",
  "The draft is with your advisor. Set a target deadline below while you wait.": "草稿在导师那里。等待期间可以在下方设定目标 deadline。",
  "Draft the paper in Overgrief and get advisor approval before submitting. You can set a target deadline any time.": "先在 Overgrief 里把 paper 写出来并拿到导师批准，再提交。目标 deadline 随时可以设。",
  "open science · closed doors": "开放科学 · 大门紧闭",
  "A little progress, a little hype.": "一点进度，一点热度。",
  "Saves Energy, moves the draft.": "省精力，推进草稿。",
  "Builds presentation readiness.": "提升展示准备度。",
  "A direction to test, not a guarantee.": "一个可以试的方向，不是保证。",
  "Only when reviews are in. Check the citations.": "只有 review 到了才能用。记得检查 citation。",
  "Ask anything: deadlines, advisors, reviewers, sleep, money, bugs, quitting. It has opinions on all of them.": "什么都可以问：deadline、导师、reviewer、睡眠、钱、bug、退学。它对这些都有看法。",
  "tool result": "工具结果",
  "one per turn. These have side effects on the paper.": "每回合一次。它们会对 paper 产生副作用。",
  "Timestamps for people who fear being scooped.": "为害怕被抢发的人提供时间戳。",
  "You have not posted anything. Neither has your competitor, probably.": "你还什么都没发。你的竞争者大概也没有。",
  "v2 will fix the typo in the title": "v2 会修好标题里的错别字",
  "Post from Overgrief when a draft is at 85% or more.": "草稿达到 85% 及以上后，可以从 Overgrief 发布。",
