  "(no reply)": "（没有回复）",
  "(read, no reply)": "（已读，没有回复）",
  "Auto-reply: I am currently away with limited access to email.": "自动回复：我目前外出，查看邮件不便。",
  "no reply.": "没有回复。",
  "yes.": "同意。",
  "no.": "没同意。",
  "{old} left. Prof. {name} is your advisor now. The relationship starts over, which is both the bad news and the good news.": "{old} 走了。现在你的导师是 {name} 教授。这段关系要从头开始，这既是坏消息，也是好消息。",
  "Hi — I know this is a transition. Let’s meet this week and figure out where things are. I have read one of your papers, which is one more than most people.": "你好——我知道这是个过渡期。这周见一面，把现在的进展理一理。我读过你的一篇 paper，比大多数人多读了一篇。",
  "Your new advisor is Prof. {name}.": "你的新导师是 {name} 教授。",
