  "If this page contradicts another page, both pages are considered authoritative.": "如果本页面与其他页面冲突，两个页面均具有最终解释权。",
  "Other paths": "其他出路",
  "MS exit: {n}/55 coursework.": "硕士退出：课程 {n}/55。",
  "Career preparation: {n}/100": "职业准备：{n}/100",
  "an industry offer is on file": "已有一份业界 offer 在档",
  "Career focus can open an industry opportunity. A different ending can still be a good one.": "把重心放在职业上，可能会打开业界的机会。不一样的结局，也可以是好结局。",
  "{e} endings · {a} achievements found on this computer": "在这台电脑上已发现 {e} 种结局 · {a} 项成就",
  "applying": "申请中",
  "Five years later, you are writing a grant at 2 a.m. and a student has just asked whether the change is small. You say yes.": "五年后，你在凌晨两点写项目申请书，一个学生刚问你那个改动是不是很小。你说是。",
  "Five years later, you lead a team. Your calendar has a color for “thinking.” Nobody has ever booked it.": "五年后，你带起了一个团队。你的日历里有一种颜色专门代表“思考”。从来没人占用过它。",
  "Two years later, you are on the market again. You are better at it. The market is not.": "两年后，你又一次上了就业市场。你比以前更擅长了。市场没有。",
  "Three years later, the startup pivots to something adjacent to your thesis. The thesis is cited in the pitch deck, in a footnote.": "三年后，这家创业公司转型去做了和你博士论文相邻的方向。pitch deck 里 cite 了那篇论文，在脚注里。",
  "That September, an offer arrives from a place you had not considered. You take it. It is fine. It is, honestly, more than fine.": "那年九月，一个你从没考虑过的地方发来 offer。你接了。还不错。说实话，不止是还不错。",
  "Ten years later, a stranger cites your second paper in a way that suggests they read it. You feel something. It is not regret, exactly.": "十年后，一个陌生人 cite 了你的第二篇 paper，引用方式看得出他真的读过。你有点情绪。倒也不完全是后悔。",
  "Two years later, you earn more than your advisor. You do not tell them. They find out anyway.": "两年后，你赚得比导师多。你没告诉他。他还是知道了。",
  "Three years later, you mentor an intern who is deciding about a PhD. You tell them the truth. They apply anyway.": "三年后，你带的一个 intern 正在纠结要不要读博。你把实话告诉了他。他还是申请了。",
  "A year later, you sleep eight hours a night and read papers for fun. The fun part surprised you.": "一年后，你每天睡八小时，还会为了消遣读 paper。让你意外的是“消遣”那部分。",
  "Two years later, in a different lab, you finish. The acknowledgments section is very carefully worded.": "两年后，在另一个实验室，你毕业了。致谢部分的措辞非常谨慎。",
  "Next cycle, you apply again, with a better statement and worse illusions.": "下一个申请季，你又申请了一次：个人陈述更好，幻想更差。",
  "A year later, in a different field, you are good at something. It counts.": "一年后，在另一个领域，你确实擅长某件事。这也算数。",
