  "Decide what this becomes": "决定它接下来变成什么",
  "Revise, reframe, expand, or let it go — in OpenRegret.": "修订证据、重讲故事、扩大贡献，或者就此放手——都在 OpenRegret 里。",
  "Open OpenRegret": "打开 OpenRegret",
  "Write the rebuttal": "写 rebuttal",
  "The window closes at the end of this month.": "窗口这个月底关闭。",
  "Your advisor is reading": "导师正在读",
  "Expected reply in {n} week(s). Nothing to do but the next thing.": "预计 {n} 周后回复。除了做下一件事，没别的可做。",
  "Submit it": "投出去",
  "Open this month: {list}.": "本月开放：{list}。",
  "Wait for the deadline": "等 deadline",
  "{venue} opens in {month}.": "{venue} 在 {month} 开放投稿。",
  "Choose where to send it": "选一个投稿场所",
  "No venue is open this month. Set a target below and the deadline month will run week by week.": "这个月没有投稿场所开放。在下面设一个目标，到了 deadline 那个月会逐周推进。",
  "Get the research to 35%": "把研究做到 35%",
  "Drafting unlocks at 35% research. You are at {n}%.": "研究到 35% 才能开始写草稿。你现在 {n}%。",
  "Plan a Research month": "把本月计划设为研究",
  "Write the draft to 60%": "把草稿写到 60%",
  "Your advisor reads it at 60% draft and 40% research. Draft {d}%, research {r}%.": "导师要草稿 60%、研究 40% 才会读。草稿 {d}%，研究 {r}%。",
  "Get the research to 40%": "把研究做到 40%",
  "The draft is long enough; the results are not. Research {r}%.": "草稿够长了，结果还不够。研究 {r}%。",
  "Send it to your advisor": "交给导师",
  "Draft {d}%, research {r}%. Both thresholds met.": "草稿 {d}%，研究 {r}%。两个门槛都过了。",
  "mean {n}/10": "均分 {n}/10",
