  "not this term": "这学期不行",
  "On it — I will have this back to you shortly.": "在做了——很快就发给你。",
  "Could this wait until after the deadline? I am at capacity this week.": "这个能等 deadline 之后再做吗？我这周已经满了。",
  "I am going to say no to this one — I need the time for the draft.": "这个我要拒绝——我需要时间写草稿。",
