  "Preliminary exam at the end of the month": "月底资格考",
  "Thesis proposal at the end of the month": "月底论文开题",
  "Dissertation defense at the end of the month": "月底博士论文答辩",
  "Rebuttal window: {venue}": "rebuttal 窗口：{venue}",
