  "You send it, and they reply, and you have nobody left in the week to reply back to. The thread sits there, warm and unanswered, which is its own kind of answer.": "你发了出去，对方回了，而这一周你已经没有余力再回过去。那个对话就停在那儿，温热且没有回音——这本身也是一种回答。",
